beforeEach(function() {
                $.terminal.defaults.formatters = formatters.slice();
                $.terminal.defaults.formatters.push([/foo/g, '[[;red;]foo bar]']);
                if (cmd) {
                    cmd.destroy();
                }
                cmd = $('<div/>').cmd();
