      if ($.test('-f', cashrcCopy)) {
        $.mv(cashrcCopy, cashrcPath);
        if ($.error()) {
          console.error('warning: unable to restore your cashrc file');
        }
      } else {
        $.rm('-f', cashrcPath);
      }
      $.rm('-rf', 'fizzlecrumbs');
    })

