before(function () {
    process.stdout.columns = 1000;
    oldCwd = process.cwd();
    oldProcessEnv = process.env;
    new $.ShellString('echo "      hello world"\nalias foo bar\n').to('a.sh');
    new $.ShellString(`export FOO=hello
