before(function(done) {
    gateways = [];
    //start remote servers
    var item, opts, gateway;
    for(var i=0, l=serverList.length; i<l; i++) {
      item = serverList[i];
      opts = {
        paths: records,
        port: item.port,
        context: {id: item.id}
      };

      gateway = Server.create(opts);
      gateways.push(gateway);
      gateway.start();
    }
    done();
  })

after(function(done) {
    //stop remote servers
    for(var i=0; i<gateways.length; i++) {
      gateways[i].stop();
    }
    done();
  })

