        table.addColumn(columnNumber);
        table.addColumn(columnBool);
        table.addColumn(columnDate);
        table.addColumn(columnObj);
        table.addColumn(columnET);
        table.addColumn(columnURL);
        table.addColumn(columnEmail);

        table.save({
